import Foundation
import UIKit

enum RecipeThumbs {
    static func url(for name: String) -> URL? {
        if let raw = table[name] { return URL(string: raw) }
        return keywordURL(name)
    }

    static func smallURL(for name: String) -> URL? {
        sized(name, width: 900)
    }

    static func heroURL(for name: String) -> URL? {
        sized(name, width: 1600)
    }

    private static func sized(_ name: String, width: Int) -> URL? {
        guard var raw = table[name] ?? keywordURL(name)?.absoluteString else { return nil }
        if raw.contains("images.unsplash.com"), let r = raw.range(of: "w=") {
            let start = r.upperBound
            let digits = raw[start...].prefix(while: { $0.isNumber })
            raw.replaceSubrange(start..<raw.index(start, offsetBy: digits.count), with: String(width))
        }
        return URL(string: raw)
    }

    private static func keywordURL(_ name: String) -> URL? {
        let blob = name.lowercased()
        for (key, raw) in keywords where blob.contains(key) {
            return URL(string: raw)
        }
        return URL(string: "https://images.unsplash.com/photo-1476224203421-9ac39bcb3327?auto=format&fit=crop&w=1200&q=80")
    }

